// Limits for the dosing unit.
const LowLimit = 0;
const HighLimit = 100;

/*<auto-generated>
***End of Global definition area***
Changes to this comment may cause incorrect behavior during document based import.
</auto-generated>*/
export function limit(value) {
  return Math.min(HighLimit, Math.max(LowLimit, value));
}

export function percent(part, whole) {
  return whole === 0 ? 0 : 100 * part / whole;
}
